let enterpriseSession=null;
async function enterpriseCall(action,extra={}){if(location.port!=='4180')throw Error('Open the local service on port 4180 first.');const r=await fetch('/api/enterprise/'+action,{method:'POST',headers:{Authorization:'Bearer '+governedToken,'Content-Type':'application/json'},body:JSON.stringify({tenant:'scholarion',course:'AIM310',...extra})});const data=await r.json();if(!r.ok)throw Error(data.error);return data;}
function enterprisePage(){return heading('Enterprise workflow controls','Scholarion Academy · Local deterministic orchestration')+`<section class="card prose"><p>Server-backed request sessions, prerequisite checks and a local human-review queue. Salesforce Agentforce, Enhanced Chat, Data Cloud and payment connectors are not connected.</p>${location.port!=='4180'?'<a class="button" href="http://127.0.0.1:4180/#enterprise-controls">Open local service</a>':''}<form id="enterprise-turn"><label>Request<textarea name="question" rows="4" maxlength="4000" required placeholder="Check registration prerequisites"></textarea></label><label>Channel<select name="channel"><option value="chat">Chat</option><option value="voice">Voice response preview</option></select></label><button class="button">Check request</button></form><p>Do not enter payment details or real student records. Requests cannot execute payments, registration or record changes.</p><button class="button secondary" id="enterprise-new">Start new request</button><button class="button secondary" id="enterprise-cases">View local CARE queue (staff)</button><div id="enterprise-result" aria-live="polite"></div></section>`;}
const beforeEnterprise=render;render=function(){if(location.hash==='#enterprise-controls'){document.getElementById('app').innerHTML=integratedShell('enterprise-controls',enterprisePage(),model.role);bind();}else beforeEnterprise();document.querySelector('.sidebar nav')?.insertAdjacentHTML('beforeend',`<a class="nav-item" href="#enterprise-controls">${icon('shield')}Enterprise controls</a>`);};
document.addEventListener('submit',async e=>{const f=e.target;if(!['enterprise-connect','enterprise-turn'].includes(f.id))return;e.preventDefault();const v=new FormData(f);try{if(f.id==='enterprise-connect'){governedToken=v.get('token');enterpriseSession=null;f.reset();toast('Token held in page memory.');return;}const result=await enterpriseCall('turn',{session:enterpriseSession,question:v.get('question'),channel:v.get('channel')});enterpriseSession=result.session;document.getElementById('enterprise-result').innerHTML=`<div class="callout"><h2>${esc(result.outcome.replaceAll('_',' '))}</h2><p>${esc(result.message)}</p><p>Clarifications: ${result.clarifications}/2 · No action executed</p>${result.case_id?`<p>Local case: ${esc(result.case_id)}</p>`:''}${result.gate_results.length?`<ul>${result.gate_results.map(g=>`<li>${esc(g.condition.replaceAll('_',' '))}: ${esc(g.reason)}</li>`).join('')}</ul>`:''}</div>`;}catch(err){document.getElementById('enterprise-result').textContent=err.message;}});
document.addEventListener('click',async e=>{if(e.target.id==='enterprise-new'){enterpriseSession=null;document.getElementById('enterprise-result').textContent='Ready for a new request.';}if(e.target.id==='enterprise-cases')try{const rows=await enterpriseCall('cases');document.getElementById('enterprise-result').innerHTML=rows.map(r=>`<article class="callout"><h3>${esc(r.trigger.replaceAll('_',' '))}</h3><p>${esc(r.id)} · ${esc(r.state)}</p><p>Local queue only. No external specialist notified.</p></article>`).join('')||'<p>No local review cases.</p>';}catch(err){document.getElementById('enterprise-result').textContent=err.message;}});
render();
